+
+      .option label {
+        cursor: pointer;
+        line-height: 1.35;
+        flex: 1;
+      }
+
+      .actions {
+        display: flex;
+        flex-wrap: wrap;
+        gap: 0.75rem;
+        align-items: center;
+        justify-content: space-between;
+        margin-top: 0.25rem;
