+        .card {
+          padding: 1.25rem;
+          border-radius: 1.25rem;
+        }
+
+        .actions {
+          align-items: stretch;
+        }
+
+        button {
+          width: 100%;
+        }
+      }
+
+      @media (forced-colors: active) {
+        body,
