<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Notification Preferences</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --panel: rgba(15, 23, 42, 0.92);
        --panel-border: rgba(148, 163, 184, 0.18);
        --text: #e5eefc;
        --muted: #9fb0cc;
        --accent: #7c9cff;
        --accent-2: #8b5cf6;
        --focus: #f9c74f;
        --shadow: 0 24px 60px rgba(2, 6, 23, 0.5);
      }

      * {
        box-sizing: border-box;
      }

      html,
      body {
        min-height: 100%;
      }

      body {
        margin: 0;
        font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
          sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, rgba(124, 156, 255, 0.2), transparent 34%),
          radial-gradient(circle at 80% 20%, rgba(139, 92, 246, 0.18), transparent 22%),
          linear-gradient(180deg, #08101f 0%, #0b1020 100%);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        padding: 0.75rem 1rem;
        border-radius: 999px;
        background: #ffffff;
        color: #0b1020;
        transform: translateY(-180%);
        transition: transform 0.2s ease;
        z-index: 10;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      main {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 2rem 1rem;
      }

      .card {
        width: min(100%, 42rem);
        background: linear-gradient(180deg, rgba(17, 24, 39, 0.98), rgba(15, 23, 42, 0.94));
        border: 1px solid var(--panel-border);
        border-radius: 1.5rem;
        box-shadow: var(--shadow);
        padding: clamp(1.5rem, 4vw, 2.25rem);
        backdrop-filter: blur(18px);
      }

      h1 {
        margin: 0 0 0.5rem;
        font-size: clamp(1.75rem, 3vw, 2.25rem);
        line-height: 1.15;
      }

      .subtitle {
        margin: 0 0 1.75rem;
        color: var(--muted);
        line-height: 1.5;
      }

      .form-field {
        display: grid;
        gap: 1.25rem;
      }

      fieldset {
        margin: 0;
        padding: 0;
        border: 0;
      }

      legend {
        margin-bottom: 0.85rem;
        font-size: 1.05rem;
        font-weight: 650;
      }

      .required {
        color: #fca5a5;
      }

      .options {
        display: grid;
        gap: 0.75rem;
      }

      .option {
        display: flex;
        align-items: center;
        gap: 0.85rem;
        padding: 0.95rem 1rem;
        border: 1px solid rgba(148, 163, 184, 0.2);
        border-radius: 1rem;
        background: rgba(15, 23, 42, 0.7);
        transition: border-color 0.2s ease, background-color 0.2s ease,
          transform 0.2s ease;
      }

      .option:hover {
        background: rgba(30, 41, 59, 0.88);
        border-color: rgba(124, 156, 255, 0.45);
        transform: translateY(-1px);
      }

      .option input {
        width: 1.1rem;
        height: 1.1rem;
        margin: 0;
        accent-color: var(--accent);
      }

      .option label {
        cursor: pointer;
        line-height: 1.35;
        flex: 1;
      }

      .actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
        align-items: center;
        justify-content: space-between;
        margin-top: 0.25rem;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 999px;
        padding: 0.9rem 1.35rem;
        font: inherit;
        font-weight: 650;
        color: #0b1020;
        background: linear-gradient(135deg, var(--accent), #a78bfa);
        box-shadow: 0 10px 25px rgba(124, 156, 255, 0.3);
        cursor: pointer;
      }

      button:hover {
        filter: brightness(1.04);
      }

      .status {
        min-height: 1.5rem;
        color: var(--muted);
      }

      :focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      @media (max-width: 480px) {
        .card {
          padding: 1.25rem;
          border-radius: 1.25rem;
        }

        .actions {
          align-items: stretch;
        }

        button {
          width: 100%;
        }
      }

      @media (forced-colors: active) {
        body,
        .card,
        .option,
        button {
          forced-color-adjust: auto;
        }

        .option,
        button {
          border: 1px solid ButtonText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main">Skip to main content</a>

    <main id="main">
      <section class="card" aria-labelledby="page-title">
        <h1 id="page-title">Notification preferences</h1>
        <p class="subtitle">Choose one way you'd like to hear from us.</p>

        <form id="notification-form" novalidate>
          <div class="form-field">
            <fieldset aria-describedby="notification-help">
              <legend>
                How do you prefer to receive notifications?
                <span class="required" aria-hidden="true">*</span>
              </legend>
              <p id="notification-help" class="subtitle">
                Select a single option before sending your preference.
              </p>

              <div class="options">
                <div class="option">
                  <input
                    type="radio"
                    id="notify-email"
                    name="notification"
                    value="Email"
                    required
                  />
                  <label for="notify-email">Email</label>
                </div>

                <div class="option">
                  <input
                    type="radio"
                    id="notify-sms"
                    name="notification"
                    value="SMS"
                    required
                  />
                  <label for="notify-sms">SMS</label>
                </div>

                <div class="option">
                  <input
                    type="radio"
                    id="notify-push"
                    name="notification"
                    value="Push Notifications"
                    required
                  />
                  <label for="notify-push">Push Notifications</label>
                </div>
              </div>
            </fieldset>

            <div class="actions">
              <button type="submit">Save preference</button>
              <p class="status" id="form-status" aria-live="polite"></p>
            </div>
          </div>
        </form>
      </section>
    </main>

    <script>
      const form = document.getElementById("notification-form");
      const status = document.getElementById("form-status");

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const selected = form.querySelector('input[name="notification"]:checked');

        if (!selected) {
          status.textContent = "Select one notification option to continue.";
          return;
        }

        status.textContent = `Preference saved: ${selected.value}.`;
      });
    </script>
  </body>
</html>
