         <h1 id="page-title">Notification preferences</h1>
         <p class="subtitle">Choose one way you'd like to hear from us.</p>

         <form id="notification-form" novalidate>
           <div class="form-field">
             <fieldset aria-describedby="notification-help">
               <legend>
                 How do you prefer to receive notifications?
                 <span class="required" aria-hidden="true">*</span>
               </legend>
               <p id="notification-help" class="subtitle">
                 Select a single option before sending your preference.
               </p>

               <div class="options">
                 <div class="option">
                   <input
                     type="radio"
                     id="notify-email"
                     name="notification"
                     value="Email"
                     required
                   />
                   <label for="notify-email">Email</label>
                 </div>

                 <div class="option">
                   <input
                     type="radio"
                     id="notify-sms"
                     name="notification"
                     value="SMS"
                     required
                   />
                   <label for="notify-sms">SMS</label>
                 </div>

                 <div class="option">
                   <input
                     type="radio"
                     id="notify-push"
                     name="notification"
                     value="Push Notifications"
                     required
                   />
                   <label for="notify-push">Push Notifications</label>
                 </div>
               </div>
             </fieldset>

             <div class="actions">
               <button type="submit">Save preference</button>
               <p class="status" id="form-status" aria-live="polite"></p>
             </div>
           </div>
         </form>
       </section>
     </main>

     <script>
       const form = document.getElementById("notification-form");
       const status = document.getElementById("form-status");

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         const selected = form.querySelector('input[name="notification"]:checked');

         if (!selected) {
           status.textContent = "Select one notification option to continue.";
           return;
         }

         status.textContent = `Preference saved: ${selected.value}.`;
       });
     </script>
   </body>
 </html>

