    focusOrder.push(await page.evaluate(() => document.activeElement && (document.activeElement.id || document.activeElement.textContent || document.activeElement.tagName)));
  }

  await page.keyboard.press('Shift+Tab');
  await page.keyboard.press('Shift+Tab');
  await page.keyboard.press('Tab');
  await page.keyboard.press('Tab');
  await page.keyboard.press('ArrowDown');
  const selectedAfterArrow = await page.$eval('#notify-sms', el => el.checked);

  await page.evaluate(() => document.getElementById('notification-form').requestSubmit());
  const emptyStatus = await page.$eval('#form-status', el => el.textContent);

  await page.click('#notify-email');
  await page.evaluate(() => document.getElementById('notification-form').requestSubmit());
  const filledStatus = await page.$eval('#form-status', el => el.textContent);

  await browser.close();
  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
    focusOrder,
    selectedAfterArrow,
    emptyStatus,
    filledStatus
  }, null, 2));
  process.exit(wcag.length ? 1 : 0);
})();
